"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["25629"],{69815(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.classificacao_abaixo_do_minimo_do_dominio","status":422,"titulo":"Classifica\xe7\xe3o de prote\xe7\xe3o de dados incompat\xedvel com o dom\xednio do fato"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.classificacao_abaixo_do_minimo_do_dominio","requisitos":["UNI-REQ-0143","UNI-REQ-0205"],"oQueAconteceu":["A classifica\xe7\xe3o de prote\xe7\xe3o de dados pertence ao vocabul\xe1rio, mas o tipo de dado do fato exige outra (UNI-REQ-0143 e UNI-REQ-0205). Texto, data e endere\xe7o identificam ou localizam a pessoa e nunca ficam abaixo de `PESSOAL`; `IDENTIFICADOR`, que \xe9 o n\xfamero de documento, s\xf3 vale para fato de texto. Por tipo de dado:","- texto: `PESSOAL`, `IDENTIFICADOR` ou `SENSIVEL`;\\n- data e endere\xe7o: `PESSOAL` ou `SENSIVEL`;\\n- booleano, categ\xf3rico e n\xfamero: qualquer uma, menos `IDENTIFICADOR`.","A recusa vale para o cadastro (`POST /api/configuracao/admin/fatos-candidato`, `POST /api/configuracao/admin/fatos-candidato/derivados` e `POST /api/configuracao/admin/fatos-candidato/agregados`), para a altera\xe7\xe3o da defini\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`), inclusive a do fato de sistema, e para a decis\xe3o de ajuste da prote\xe7\xe3o de dados (`POST /api/configuracao/admin/protecao-do-catalogo`), em que a classifica\xe7\xe3o recomendada tamb\xe9m precisa servir ao tipo de dado do fato. Na decis\xe3o, `field` \xe9 `classificacaoRecomendada`; nas demais opera\xe7\xf5es, `classificacaoProtecao`. No fato derivado por regra o tipo de dado \xe9 booleano ou categ\xf3rico, e no resumo de grupo ele \xe9 inferido do fato de membro.","A confer\xeancia da hip\xf3tese legal contra a classifica\xe7\xe3o \xe9 independente desta, e as duas recusas podem vir juntas na lista `errors`. Nada \xe9 gravado."],"comoResolver":["Escolha uma classifica\xe7\xe3o que o tipo de dado aceita, conforme a lista acima. Um n\xfamero de documento (CPF, RG, passaporte) \xe9 sempre um fato de texto com classifica\xe7\xe3o `IDENTIFICADOR`. Um dado pessoal em texto, data ou endere\xe7o n\xe3o pode ser `PUBLICO` nem `INTERNO`. A classifica\xe7\xe3o inv\xe1lida por outro motivo recebe [a recusa de classifica\xe7\xe3o fora do vocabul\xe1rio](/erros/uniplus.configuracao.fato_candidato.classificacao_protecao_invalida)."],"ondeAparece":["Cadastro de um fato do cat\xe1logo (declarado, derivado ou resumo de grupo)","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo","Decis\xe3o sobre a prote\xe7\xe3o de dados de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);